// Extract invoice file URLs from the webhook request body
const body = $input.first().json.body || $input.first().json;
const invoiceFiles = body.invoiceFiles || [];

if (!invoiceFiles.length) {
  throw new Error('No invoice files provided in request body');
}

// Output each file as a separate item for parallel processing
return invoiceFiles.map((file, index) => ({
  json: {
    fileUrl: file.fileUrl || file.url || file,
    fileName: file.fileName || `invoice_${index + 1}`,
    fileIndex: index
  }
}));

// Convert downloaded file to base64 for Doubao API
const binaryData = $input.first().binary;
if (!binaryData || !binaryData.data) {
  throw new Error('No binary data found for file: ' + $input.first().json.fileName);
}

const binaryKey = Object.keys(binaryData)[0];
const fileData = binaryData[binaryKey];
const base64Content = fileData.data; // n8n stores binary as base64
const mimeType = fileData.mimeType || 'image/jpeg';

return [{
  json: {
    fileName: $input.first().json.fileName,
    fileIndex: $input.first().json.fileIndex,
    base64Image: base64Content,
    mimeType: mimeType
  }
}];

