// Parse Doubao API response and extract invoice data
const response = $input.first().json;
const fileName = $('Convert to Base64').first().json.fileName;
const fileIndex = $('Convert to Base64').first().json.fileIndex;

let invoiceData = {
  invoice_type: null,
  invoice_amount: null,
  invoice_date: null,
  vendor_name: null,
  invoice_number: null,
  tax_amount: 0,
  description: null
};

try {
  const content = response.choices[0].message.content;

  // Try to parse JSON from the response
  // The LLM might wrap it in markdown code blocks
  let jsonStr = content;
  const jsonMatch = content.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (jsonMatch) {
    jsonStr = jsonMatch[1].trim();
  }

  invoiceData = JSON.parse(jsonStr);

  // Ensure amount is a number
  if (invoiceData.invoice_amount !== null) {
    invoiceData.invoice_amount = parseFloat(invoiceData.invoice_amount);
  }
  if (invoiceData.tax_amount !== null) {
    invoiceData.tax_amount = parseFloat(invoiceData.tax_amount) || 0;
  }
} catch (e) {
  // If parsing fails, return with error status
  return [{
    json: {
      fileIndex: fileIndex,
      fileName: fileName,
      recognition_status: 'FAILED',
      error: 'Failed to parse LLM response: ' + e.message,
      raw_response: response.choices?.[0]?.message?.content || JSON.stringify(response)
    }
  }];
}

return [{
  json: {
    fileIndex: fileIndex,
    fileName: fileName,
    recognition_status: 'SUCCESS',
    ...invoiceData
  }
}];

// Aggregate all invoice recognition results
const items = $input.all();

const results = items.map(item => item.json);

// Calculate totals
const successItems = results.filter(r => r.recognition_status === 'SUCCESS');
const failedItems = results.filter(r => r.recognition_status === 'FAILED');

const totalAmount = successItems.reduce((sum, item) => {
  return sum + (parseFloat(item.invoice_amount) || 0);
}, 0);

const totalTax = successItems.reduce((sum, item) => {
  return sum + (parseFloat(item.tax_amount) || 0);
}, 0);

// Group by expense type
const expenseByType = {};
for (const item of successItems) {
  const type = item.invoice_type || '其他';
  if (!expenseByType[type]) {
    expenseByType[type] = { count: 0, amount: 0 };
  }
  expenseByType[type].count++;
  expenseByType[type].amount += parseFloat(item.invoice_amount) || 0;
}

// Round amounts
for (const type in expenseByType) {
  expenseByType[type].amount = Math.round(expenseByType[type].amount * 100) / 100;
}

return [{
  json: {
    success: true,
    summary: {
      totalAmount: Math.round(totalAmount * 100) / 100,
      totalTax: Math.round(totalTax * 100) / 100,
      totalInvoices: results.length,
      successCount: successItems.length,
      failedCount: failedItems.length,
      expenseByType: expenseByType
    },
    invoices: results,
    expenseItems: successItems.map((item, idx) => ({
      expense_type: item.invoice_type || '其他',
      expense_date: item.invoice_date,
      amount: parseFloat(item.invoice_amount) || 0,
      description: item.description || item.vendor_name || '',
      sort_order: idx + 1
    }))
  }
}];
